package live.linghe.privateinput;
import java.io.*;import java.math.BigInteger;import java.util.*;import org.json.*;
/** Native cumulative components + authenticated cloud projection. No timing,
 * network, UI or alternate learning algorithm. Mirrors the shared contract. */
final class CloudLearningState {
 static final String ALGORITHM="shared-lexeme-decay-v2";
 JSONObject value;CloudLearningState(JSONObject value){this.value=value;}
 static BigInteger number(JSONObject object,String key)throws Exception{return LosslessJson.unsigned(object.get(key));}
 static String id(JSONObject entry)throws Exception{return LearningModel.canonical(entry.getString("reading")+'\u001f'+entry.getString("text"));}
 static CloudLearningState fresh(String owner,String producer,String installation,BigInteger generation,BigInteger consent)throws Exception{return new CloudLearningState(new JSONObject().put("version",1).put("owner",owner).put("producer",PersonalLexicon.uuid(producer)).put("installation",PersonalLexicon.uuid(installation)).put("generation",generation).put("consent",consent).put("accepted",new JSONObject()).put("represented",new JSONObject()).put("baselineComplete",false).put("terms",new JSONObject()).put("fences",new JSONObject()).put("modelVersion",0).put("ready",false));}
 CloudLearningState copy()throws Exception{return new CloudLearningState(LosslessJson.object(CloudLearningCanonical.encode(value),12*1024*1024));}
 void validate(CloudLearningPolicy policy)throws Exception{
  if(value.getInt("version")!=1||!PersonalLexicon.uuid(value.getString("producer")).equals(value.getString("producer"))||number(value,"generation").signum()<=0||number(value,"consent").signum()<=0)throw new IOException("cloud cache metadata");PersonalLexicon.uuid(value.getString("installation"));String producer=value.getString("producer");
  for(String field:new String[]{"accepted","represented","recoveryRows"}){JSONObject rows=value.optJSONObject(field);if(rows==null)continue;if(rows.length()>5000)throw new IOException("cloud cache component capacity");Iterator<String> keys=rows.keys();while(keys.hasNext()){String key=keys.next();LearningModel.Entry row=LearningModel.Entry.decode(rows.getJSONObject(key));if(!row.id().equals(key)||row.counts.size()!=1||!row.counts.containsKey(producer)||!policy.eligible(row.reading,row.text))throw new IOException("cloud cache component");}}
  JSONObject receipt=value.optJSONObject("receipt");if(receipt!=null&&(!producer.equals(PersonalLexicon.uuid(receipt.getString("producer_id")))||!componentDigest(producer,value.getJSONObject("accepted")).equals(receipt.getString("component_digest"))))throw new IOException("cloud cache receipt digest");
  if(value.has("pending")){JSONObject pending=value.getJSONObject("pending");if(!producer.equals(PersonalLexicon.uuid(pending.getString("producer_id")))||!number(pending,"generation").equals(number(value,"generation"))||!number(pending,"consent_version").equals(number(value,"consent"))||pending.getJSONArray("records").length()>128)throw new IOException("cloud cache pending binding");PersonalLexicon.uuid(pending.getString("publication_id"));Set<String> seen=new HashSet<>();for(int n=0;n<pending.getJSONArray("records").length();n++){LearningModel.Entry row=LearningModel.Entry.decode(pending.getJSONArray("records").getJSONObject(n));if(!seen.add(row.id())||row.counts.size()!=1||!row.counts.containsKey(producer)||!policy.eligible(row.reading,row.text))throw new IOException("cloud cache pending component");}}
  JSONObject terms=value.getJSONObject("terms"),fences=value.getJSONObject("fences");if(terms.length()>5000||fences.length()>10000)throw new IOException("cloud cache term capacity");Iterator<String> names=terms.keys();while(names.hasNext()){String key=names.next();JSONObject row=terms.getJSONObject(key),fence=fences.getJSONObject(key);if(!id(row).equals(key)||!"shared".equals(row.getString("layout"))||!policy.eligible(row.getString("reading"),row.getString("text"))||number(row,"weight").compareTo(BigInteger.valueOf(200000))>0||!(row.get("pinned") instanceof Boolean)||!number(row,"term_generation").equals(number(fence,"generation"))||fence.getBoolean("deleted"))throw new IOException("cloud cache model term");}
  if(number(value,"modelVersion").signum()>0){JSONObject full=new JSONObject().put("generation",value.get("generation")).put("algorithm_version",ALGORITHM).put("upserts",orderedRows(terms)).put("watermarks",value.getJSONArray("watermarks")).put("producer_watermarks",value.getJSONArray("producerWatermarks"));if(!CloudLearningCanonical.hash(full).equals(value.getString("modelHash")))throw new IOException("cloud cache model checksum");}
  if(value.optBoolean("ready")){if(!value.optBoolean("shadowVerified")||!value.optBoolean("baselineComplete")||value.has("pending")||receipt==null)throw new IOException("cloud cache shadow state");boolean matched=false;JSONArray marks=value.getJSONArray("producerWatermarks");for(int n=0;n<marks.length();n++){JSONObject mark=marks.getJSONObject(n);if(producer.equals(mark.getString("producer_id")))matched=number(mark,"producer_revision").equals(number(receipt,"producer_revision"))&&mark.getString("component_digest").equals(receipt.getString("component_digest"));}if(!matched)throw new IOException("cloud cache producer watermark");}
 }
 private static JSONObject merge(JSONObject first,JSONObject second)throws Exception{LearningModel.Entry a=LearningModel.Entry.decode(first),b=LearningModel.Entry.decode(second);if(a.pinVersion.compareTo(b.pinVersion)==0&&a.pinned!=b.pinned)throw new IOException("cloud pin equivocation");return a.merging(b).json();}
 static JSONObject project(List<LearningModel.Entry> entries,String producer,CloudLearningPolicy policy,JSONObject accepted)throws Exception{producer=PersonalLexicon.uuid(producer);JSONObject rows=new JSONObject();for(LearningModel.Entry entry:entries){if(!policy.eligible(entry.reading,entry.text))continue;long own=0;boolean owns=false;for(Map.Entry<String,Long> count:entry.counts.entrySet())if(producer.equalsIgnoreCase(count.getKey())){own=Math.max(own,count.getValue());owns=true;}if(!owns&&!producer.equalsIgnoreCase(entry.pinVersion.device)&&!accepted.has(entry.id()))continue;JSONObject row=entry.json();row.put("counts",new JSONObject().put(producer,own));rows.put(entry.id(),row);}return rows;}
 static JSONArray orderedRows(JSONObject rows)throws Exception{List<String> keys=new ArrayList<>();Iterator<String> names=rows.keys();while(names.hasNext())keys.add(names.next());Collections.sort(keys,(a,b)->{try{JSONObject x=rows.getJSONObject(a),y=rows.getJSONObject(b);int c=x.getString("reading").compareTo(y.getString("reading"));return c!=0?c:x.getString("text").compareTo(y.getString("text"));}catch(JSONException e){throw new IllegalArgumentException(e);}});JSONArray result=new JSONArray();for(String key:keys)result.put(rows.getJSONObject(key));return result;}
 static String componentDigest(String producer,JSONObject rows)throws Exception{return CloudLearningCanonical.hash(new JSONObject().put("producer_id",PersonalLexicon.uuid(producer)).put("records",orderedRows(rows)));}
 JSONObject prepare(JSONObject projected)throws Exception{if(value.has("pending"))return value.getJSONObject("pending");JSONObject accepted=value.getJSONObject("accepted");if(value.has("recoveryRows")){projected=LosslessJson.object(CloudLearningCanonical.encode(projected),4*1024*1024);JSONObject recovery=value.getJSONObject("recoveryRows");Iterator<String> restore=recovery.keys();while(restore.hasNext()){String key=restore.next();JSONObject row=recovery.getJSONObject(key);projected.put(key,projected.has(key)?merge(projected.getJSONObject(key),row):row);}}JSONArray changed=new JSONArray();JSONArray ordered=value.optBoolean("forceEmptyHandshake")?new JSONArray():orderedRows(projected);for(int i=0;i<ordered.length()&&changed.length()<128;i++){JSONObject row=ordered.getJSONObject(i);String key=id(row);JSONObject candidate=accepted.has(key)?merge(accepted.getJSONObject(key),row):row;if(!accepted.has(key)||!CloudLearningCanonical.encode(accepted.get(key)).equals(CloudLearningCanonical.encode(candidate)))changed.put(candidate);}if(changed.length()==0&&value.has("receipt")&&!value.optBoolean("forceEmptyHandshake")){value.put("baselineComplete",true);value.remove("recoveryRows");return null;}JSONObject pending=new JSONObject().put("generation",value.get("generation")).put("consent_version",value.get("consent")).put("installation_id",value.getString("installation")).put("producer_id",value.getString("producer")).put("publication_id",UUID.randomUUID().toString().toUpperCase(Locale.ROOT)).put("history_mode",value.optBoolean("baselineComplete")?"incremental":"historical_undated").put("records",changed);value.put("pending",pending).put("ready",false);return pending;}
 void receive(JSONObject receipt)throws Exception{JSONObject pending=value.getJSONObject("pending");if(!PersonalLexicon.uuid(receipt.getString("accepted_publication_id")).equals(PersonalLexicon.uuid(pending.getString("publication_id")))||!PersonalLexicon.uuid(receipt.getString("producer_id")).equals(value.getString("producer"))||!number(receipt,"generation").equals(number(value,"generation"))||!number(receipt,"consent_version").equals(number(value,"consent"))||number(receipt,"changed_records").compareTo(BigInteger.valueOf(pending.getJSONArray("records").length()))>0)throw new IOException("cloud receipt binding");JSONObject accepted=LosslessJson.object(CloudLearningCanonical.encode(value.getJSONObject("accepted")),4*1024*1024);JSONArray rows=pending.getJSONArray("records");for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);String key=id(row);accepted.put(key,accepted.has(key)?merge(accepted.getJSONObject(key),row):row);}if(!componentDigest(value.getString("producer"),accepted).equals(receipt.getString("component_digest")))throw new IOException("cloud component digest");value.put("accepted",accepted).put("receipt",receipt);value.remove("pending");if(value.optBoolean("forceEmptyHandshake")){value.put("baselineComplete",true);value.remove("forceEmptyHandshake");}}
 void recover(JSONObject recovered,CloudLearningPolicy policy)throws Exception{
  if(!(recovered.get("exists") instanceof Boolean)||!PersonalLexicon.uuid(recovered.getString("producer_id")).equals(value.getString("producer")))throw new IOException("cloud recovery identity");JSONArray rows=recovered.getJSONArray("records");if(rows.length()>5000)throw new IOException("cloud recovery bound");JSONObject accepted=new JSONObject();for(int i=0;i<rows.length();i++){LearningModel.Entry row=LearningModel.Entry.decode(rows.getJSONObject(i));if(!policy.eligible(row.reading,row.text)||row.counts.size()!=1||!row.counts.containsKey(value.getString("producer"))||accepted.has(row.id()))throw new IOException("cloud recovery component");accepted.put(row.id(),row.json());}
  if(!componentDigest(value.getString("producer"),accepted).equals(recovered.getString("component_digest"))||recovered.getBoolean("exists")!=(number(recovered,"producer_revision").signum()>0)||!recovered.getBoolean("exists")&&rows.length()!=0)throw new IOException("cloud recovery digest");
  JSONObject retained=LosslessJson.object(CloudLearningCanonical.encode(value.getJSONObject("accepted")),4*1024*1024);if(value.has("recoveryRows")){JSONObject old=value.getJSONObject("recoveryRows");Iterator<String> names=old.keys();while(names.hasNext()){String key=names.next();retained.put(key,retained.has(key)?merge(retained.getJSONObject(key),old.getJSONObject(key)):old.getJSONObject(key));}}
  if(value.has("pending")){JSONArray pending=value.getJSONObject("pending").getJSONArray("records");for(int i=0;i<pending.length();i++){JSONObject row=pending.getJSONObject(i);String key=id(row);retained.put(key,retained.has(key)?merge(retained.getJSONObject(key),row):row);}value.remove("pending");}
  value.put("accepted",accepted).put("ready",false).put("recovered",true).put("recoveryRows",retained).put("baselineComplete",false).put("forceEmptyHandshake",recovered.getBoolean("exists"));value.remove("receipt");
 }
 void stage(JSONObject delta,CloudLearningPolicy policy)throws Exception{CloudLearningState next=copy();next.stageVerified(delta,policy);value=next.value;}
 private void stageVerified(JSONObject delta,CloudLearningPolicy policy)throws Exception{
  if(!number(delta,"generation").equals(number(value,"generation"))||!number(delta,"from_version").equals(number(value,"modelVersion"))||number(delta,"to_version").compareTo(number(value,"modelVersion"))<0||!ALGORITHM.equals(delta.getString("algorithm_version")))throw new IOException("cloud model version");
  JSONObject terms=value.getJSONObject("terms"),fences=value.getJSONObject("fences");JSONArray up=delta.getJSONArray("upserts"),down=delta.getJSONArray("tombstones");if(up.length()>5000||down.length()>5000)throw new IOException("cloud model bound");Set<String> seen=new HashSet<>();if(number(delta,"to_version").equals(number(value,"modelVersion"))&&(up.length()!=0||down.length()!=0))throw new IOException("cloud immutable model version");
  for(int pass=0;pass<2;pass++){JSONArray rows=pass==0?up:down;for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);String key=id(row);if(!"shared".equals(row.getString("layout"))||!policy.eligible(row.getString("reading"),row.getString("text"))||!seen.add(key))throw new IOException("cloud term policy");BigInteger generation=number(row,"term_generation");if(fences.has(key)&&generation.compareTo(number(fences.getJSONObject(key),"generation"))<0)throw new IOException("cloud generation rollback");if(pass==0){if(number(row,"weight").compareTo(BigInteger.valueOf(200000))>0||!(row.get("pinned") instanceof Boolean))throw new IOException("cloud term weight");terms.put(key,new JSONObject().put("reading",row.getString("reading")).put("text",row.getString("text")).put("layout","shared").put("term_generation",generation).put("weight",number(row,"weight")).put("pinned",row.getBoolean("pinned")));}else terms.remove(key);fences.put(key,new JSONObject().put("generation",generation).put("deleted",pass==1));}}
  if(terms.length()>5000||fences.length()>10000)throw new IOException("cloud model capacity");JSONArray rawWatermarks=delta.getJSONArray("watermarks"),rawProducers=delta.getJSONArray("producer_watermarks"),watermarks=new JSONArray(),producers=new JSONArray();Set<String> deviceMarks=new HashSet<>();for(int i=0;i<rawWatermarks.length();i++){JSONObject raw=rawWatermarks.getJSONObject(i);String device=PersonalLexicon.uuid(raw.getString("device_id")),installation=PersonalLexicon.uuid(raw.getString("installation_id")),key=device+"/"+installation+"/"+number(raw,"consent_version");if(!deviceMarks.add(key))throw new IOException("cloud duplicate watermark");watermarks.put(new JSONObject().put("device_id",device).put("installation_id",installation).put("consent_version",number(raw,"consent_version")).put("device_seq",number(raw,"device_seq")));}for(int i=0;i<rawProducers.length();i++){JSONObject raw=rawProducers.getJSONObject(i);producers.put(new JSONObject().put("producer_id",PersonalLexicon.uuid(raw.getString("producer_id"))).put("producer_revision",number(raw,"producer_revision")).put("component_digest",raw.getString("component_digest")));}if(watermarks.length()>512||producers.length()>512)throw new IOException("cloud watermark bound");Set<String> producerIDs=new HashSet<>();JSONObject ownMark=null;String previous="";for(int i=0;i<producers.length();i++){JSONObject mark=producers.getJSONObject(i);String producer=PersonalLexicon.uuid(mark.getString("producer_id"));if(!producerIDs.add(producer)||producer.compareTo(previous)<0||!mark.getString("component_digest").matches("[0-9a-f]{64}"))throw new IOException("cloud producer watermark");number(mark,"producer_revision");previous=producer;if(producer.equals(value.getString("producer")))ownMark=mark;}
  JSONObject full=new JSONObject().put("generation",value.get("generation")).put("algorithm_version",ALGORITHM).put("upserts",orderedRows(terms)).put("watermarks",watermarks).put("producer_watermarks",producers);if(!CloudLearningCanonical.hash(full).equals(delta.getString("model_sha256")))throw new IOException("cloud model digest");
  boolean ready=value.optBoolean("baselineComplete")&&!value.has("pending")&&value.has("receipt")&&!delta.getBoolean("has_more")&&number(delta,"to_version").signum()>0;JSONObject receipt=value.optJSONObject("receipt");ready&=ownMark!=null&&receipt!=null&&number(ownMark,"producer_revision").equals(number(receipt,"producer_revision"))&&ownMark.getString("component_digest").equals(receipt.getString("component_digest"));
  if(ready)value.put("represented",LosslessJson.object(CloudLearningCanonical.encode(value.getJSONObject("accepted")),4*1024*1024));value.put("modelVersion",delta.get("to_version")).put("modelHash",delta.getString("model_sha256")).put("producerWatermarks",producers).put("watermarks",watermarks).put("ready",ready).put("shadowVerified",ready);
 }
}
